private int
/*ARGSUSED*/
do_bid_note(struct magic_set *ms, unsigned char *nbuf, uint32_t type,
    int swap __attribute__((__unused__)), uint32_t namesz, uint32_t descsz,
    size_t noff, size_t doff, int *flags)
{
        if (namesz == 4 && strcmp(RCAST(char *, &nbuf[noff]), "GNU") == 0 &&
            type == NT_GNU_BUILD_ID && (descsz >= 4 && descsz <= 20)) {
                uint8_t desc[20];
                const char *btype;
                uint32_t i;
                *flags |= FLAGS_DID_BUILD_ID;
                switch (descsz) {
                case 8:
                    btype = "xxHash";
                    break;
                case 16:
                    btype = "md5/uuid";
                    break;
                case 20:
                    btype = "sha1";
                    break;
                default:
                    btype = "unknown";
                    break;
                }
                if (file_printf(ms, ", BuildID[%s]=", btype) == -1)
                        return -1;
                memcpy(desc, &nbuf[doff], descsz);
                for (i = 0; i < descsz; i++)
                    if (file_printf(ms, "%02x", desc[i]) == -1)
                        return -1;
                return 1;
        }
        if (namesz == 4 && strcmp(RCAST(char *, &nbuf[noff]), "Go") == 0 &&
            type == NT_GO_BUILD_ID && descsz < 128) {
                char buf[256];
                if (file_printf(ms, ", Go BuildID=%s",
                    file_copystr(buf, sizeof(buf), descsz,
                    RCAST(const char *, &nbuf[doff]))) == -1)
                        return -1;
                return 1;
        }
        return 0;
}

private int
do_os_note(struct magic_set *ms, unsigned char *nbuf, uint32_t type,
    int swap, uint32_t namesz, uint32_t descsz,
    size_t noff, size_t doff, int *flags)
{
        const char *name = RCAST(const char *, &nbuf[noff]);

        if (namesz == 5 && strcmp(name, "SuSE") == 0 &&
                type == NT_GNU_VERSION && descsz == 2) {
                *flags |= FLAGS_DID_OS_NOTE;
                if (file_printf(ms, ", for SuSE %d.%d", nbuf[doff],
                    nbuf[doff + 1]) == -1)
                    return -1;
            return 1;
        }

        if (namesz == 4 && strcmp(name, "GNU") == 0 &&
            type == NT_GNU_VERSION && descsz == 16) {
                uint32_t desc[4];
                memcpy(desc, &nbuf[doff], sizeof(desc));

                *flags |= FLAGS_DID_OS_NOTE;
                if (file_printf(ms, ", for GNU/") == -1)
                        return -1;
                switch (elf_getu32(swap, desc[0])) {
                case GNU_OS_LINUX:
                        if (file_printf(ms, "Linux") == -1)
                                return -1;
                        break;
                case GNU_OS_HURD:
                        if (file_printf(ms, "Hurd") == -1)
                                return -1;
                        break;
                case GNU_OS_SOLARIS:
                        if (file_printf(ms, "Solaris") == -1)
                                return -1;
                        break;
                case GNU_OS_KFREEBSD:
                        if (file_printf(ms, "kFreeBSD") == -1)
                                return -1;
                        break;
                case GNU_OS_KNETBSD:
                        if (file_printf(ms, "kNetBSD") == -1)
                                return -1;
                        break;
                default:
                        if (file_printf(ms, "<unknown>") == -1)
                                return -1;
                }
                if (file_printf(ms, " %d.%d.%d", elf_getu32(swap, desc[1]),
                    elf_getu32(swap, desc[2]), elf_getu32(swap, desc[3])) == -1)
                        return -1;
                return 1;
        }

        if (namesz == 7 && strcmp(name, "NetBSD") == 0) {
                if (type == NT_NETBSD_VERSION && descsz == 4) {
                        *flags |= FLAGS_DID_OS_NOTE;
                        if (do_note_netbsd_version(ms, swap, &nbuf[doff]) == -1)
                                return -1;
                        return 1;
                }
        }

        if (namesz == 8 && strcmp(name, "FreeBSD") == 0) {
                if (type == NT_FREEBSD_VERSION && descsz == 4) {
                        *flags |= FLAGS_DID_OS_NOTE;
                        if (do_note_freebsd_version(ms, swap, &nbuf[doff])
                            == -1)
                                return -1;
                        return 1;
                }
        }

        if (namesz == 8 && strcmp(name, "OpenBSD") == 0 &&
            type == NT_OPENBSD_VERSION && descsz == 4) {
                *flags |= FLAGS_DID_OS_NOTE;
                if (file_printf(ms, ", for OpenBSD") == -1)
                        return -1;
                /* Content of note is always 0 */
                return 1;
        }

        if (namesz == 10 && strcmp(name, "DragonFly") == 0 &&
            type == NT_DRAGONFLY_VERSION && descsz == 4) {
                uint32_t desc;
                *flags |= FLAGS_DID_OS_NOTE;
                if (file_printf(ms, ", for DragonFly") == -1)
                        return -1;
                memcpy(&desc, &nbuf[doff], sizeof(desc));
                desc = elf_getu32(swap, desc);
                if (file_printf(ms, " %d.%d.%d", desc / 100000,
                    desc / 10000 % 10, desc % 10000) == -1)
                        return -1;
                return 1;
        }
        return 0;
}

private int
do_pax_note(struct magic_set *ms, unsigned char *nbuf, uint32_t type,
    int swap, uint32_t namesz, uint32_t descsz,
    size_t noff, size_t doff, int *flags)
{
        const char *name = RCAST(const char *, &nbuf[noff]);

        if (namesz == 4 && strcmp(name, "PaX") == 0 &&
            type == NT_NETBSD_PAX && descsz == 4) {
                static const char *pax[] = {
                    "+mprotect",
                    "-mprotect",
                    "+segvguard",
                    "-segvguard",
                    "+ASLR",
                    "-ASLR",
                };
                uint32_t desc;
                size_t i;
                int did = 0;

                *flags |= FLAGS_DID_NETBSD_PAX;
                memcpy(&desc, &nbuf[doff], sizeof(desc));
                desc = elf_getu32(swap, desc);

                if (desc && file_printf(ms, ", PaX: ") == -1)
                        return -1;

                for (i = 0; i < __arraycount(pax); i++) {
                        if (((1 << CAST(int, i)) & desc) == 0)
                                continue;
                        if (file_printf(ms, "%s%s", did++ ? "," : "",
                            pax[i]) == -1)
                                return -1;
                }
                return 1;
        }
        return 0;
}

